import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.io.ObjectInputStream;

public class SecureServer {
    // Define a whitelist of allowed classes to prevent unauthorized deserialization
    private static final String[] ALLOWED_CLASSES = {"java.lang.String", "java.util.ArrayList", "com.example.UserDTO"};

    public static void main(String[] args) throws Exception {
        ServerSocket serverSocket = new ServerSocket(8080);
        System.out.println("Secure server listening on port 8080...");

        while (true) {
            try (Socket socket = serverSocket.accept();
                 // Use a custom ObjectInputStream that implements look-ahead deserialization
                 SafeObjectInputStream ois = new SafeObjectInputStream(socket.getInputStream())) {

                // SECURE: The stream validates the class type before instantiating the object
                Object obj = ois.readObject();
                System.out.println("Received object: " + obj.toString());
            } catch (Exception e) {
                System.err.println("Blocked potentially malicious deserialization attempt: " + e.getMessage());
            }
        }
    }

    // Custom implementation to enforce a whitelist
    public static class SafeObjectInputStream extends ObjectInputStream {
        public SafeObjectInputStream(InputStream in) throws IOException {
            super(in);
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
            // Check if the class being deserialized is in our whitelist
            for (String allowedClass : ALLOWED_CLASSES) {
                if (desc.getName().equals(allowedClass)) {
                    return super.resolveClass(desc);
                }
            }
            // Throw an exception if the class is not recognized, preventing gadget chain attacks
            throw new InvalidClassException("Unauthorized deserialization attempt: ", desc.getName());
        }
    }
}
